SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱祁镇即皇帝位", "description": "宣德10年（1435年）正月，朱祁镇即皇帝位。", "start_year": 1435, "end_year": 1435, "time_original": "宣德10年（1435年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "66d261b1-d254-582b-91e0-5cf32aedba56"}, {"title": "明英宗按遗诏请皇太后决定大事", "description": "宣德十年正月，明英宗朱祁镇依照明宣宗的遗诏，将国家重大事务禀报皇太后张氏后办理。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be8a7ce4-4ce6-5af0-9aaa-811d7f5e1bd6"}, {"title": "明英宗大赦天下，定来年为正统元年", "description": "宣德十年正月，明英宗朱祁镇即位后大赦天下，并定次年为正统元年。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "567d4e0a-66e1-5f0a-9f5d-db7ff0fe86d0"}, {"title": "明廷开始停办午朝", "description": "宣德十年正月，《明史》本纪记朝廷开始停办午朝。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b8f06f27-eab0-5907-9b99-0547fb8fe0c7"}, {"title": "蹇义去世", "description": "宣德10年（年号对照1435年）正月，蹇义去世。", "start_year": 1435, "end_year": 1435, "time_original": "宣德10年（年号对照1435年）正月；公元年核为1435年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "8944d5b9-d70e-5e12-bc5a-c2c0a8b6f444"}, {"title": "黄福奉命参赞南京守备事务", "description": "宣德十年正月辛丑，户部尚书黄福奉命协助处理南京守备的重要事务。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c94ad08-80c2-5ace-b8b1-ed0224f37832"}, {"title": "明英宗尊张氏为太皇太后", "description": "宣德十年二月戊申，明英宗朱祁镇尊皇太后张氏为太皇太后。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年二月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e4b30f4-eb52-59ea-a394-8ad8c348ebaf"}, {"title": "明英宗尊孙氏为皇太后", "description": "宣德十年二月庚戌，明英宗朱祁镇尊明宣宗皇后孙氏为皇太后。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9cba746a-0b4d-539c-9740-d1b32d528794"}, {"title": "朱祁钰被封为郕王", "description": "宣德十年二月辛亥，明英宗朱祁镇封弟弟朱祁钰为郕王。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b9ea162-7214-52e5-a4cc-43c6daa10a35"}, {"title": "明廷命各官署停止冗余开支", "description": "宣德十年二月甲寅，朝廷下令停止各官署多余的开支。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年二月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d229680e-6bfb-54ab-837c-1721a2bbbf70"}, {"title": "明廷放归教坊司三千八百余名乐工", "description": "宣德十年三月戊寅，朝廷放归教坊司三千八百余名乐工。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年三月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ac91b38-d945-545a-880b-8c410a2476f5"}, {"title": "明廷撤去陵工劳役一万七千人", "description": "宣德十年三月辛巳，朝廷撤去陵工所用劳役一万七千人。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9cf9a8f1-1ac3-56b9-8260-32b577210e1a"}, {"title": "明廷规定死刑临决前须三次复奏", "description": "宣德十年三月丙申，明廷告谕三法司，在执行死刑前须三次复奏，然后才执行。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年三月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e328477a-4908-5c9a-9c97-8307c2c093c2"}, {"title": "明廷令元代学士吴澄在孔子庙庭从祀", "description": "宣德十年四月壬戌，朝廷决定在孔子庙庭祭祀元代学士吴澄。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年四月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "31b98ca0-c238-5d73-81b7-943476edf2fa"}, {"title": "明廷因久旱考察两司及府州县官员", "description": "宣德十年四月丁卯，朝廷因长久干旱，考察布政、按察两司及府州县官员。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年四月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e46e96f3-eff0-513f-982e-57a3afc4d082"}, {"title": "明廷派给事中、御史到畿南等处捕蝗", "description": "宣德十年四月戊辰，朝廷派给事中、御史到畿南、山东、河南和淮安捕蝗。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年四月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7c834d6e-a71a-5061-9f0e-ec1185fcf3e5"}, {"title": "明英宗未准重新核查浙江、苏松荒田减税", "description": "宣德十年五月壬午，户部称浙江、苏州、松江荒田已经减免二百七十七万多石税粮，请求再核。明英宗担心核查导致加额、增加百姓负担，没有准许。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年五月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4641f135-5dcc-5731-9946-4e9b2bc185c3"}, {"title": "明廷命各地掩埋露天遗骸", "description": "宣德十年六月丁未，朝廷命各地掩埋暴露在外的遗骸。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年六月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cbf69715-16d0-5e11-ab28-7ae7a3ee8a9b"}, {"title": "明宣宗朱瞻基正式安葬于景陵", "description": "宣德十年六月辛酉，谥号为章皇帝的明宣宗朱瞻基安葬于景陵。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年六月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7612a7a3-8951-51ae-9197-c255975f8095"}, {"title": "明廷减免山西一半夏税", "description": "宣德十年七月丙子，朝廷免去山西一半夏税。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年七月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82beaec7-d208-5c16-b08e-687decd51c03"}, {"title": "明廷裁减光禄寺四千七百余名膳夫", "description": "宣德十年八月丙午，朝廷裁减光禄寺四千七百余名负责供膳的人。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年八月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a98c26b3-f8f7-52e2-9260-4903ed2c1835"}, {"title": "明廷命督漕和巡抚官每年八月入京议事", "description": "宣德十年九月壬辰，朝廷下诏，督办漕运的总兵与各地巡抚每年八月到京，与朝臣商议政事。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年九月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72664fd8-6553-5e9b-ac05-a5bf71f8d5b8"}, {"title": "王振掌管司礼监", "description": "宣德十年九月，宦官王振掌理司礼监。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a567f5e5-888c-5413-9502-dd14ec6f26d2"}, {"title": "明廷派使者告谕阿台和朵儿只伯", "description": "宣德十年十月壬寅，朝廷派使者前去告谕阿台与朵儿只伯。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年十月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "150bde8f-1361-5c8e-b579-af7ed1717779"}, {"title": "明廷命各地卫所设立学校", "description": "宣德十年十月辛亥，朝廷下诏命各地卫所设立学校。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年十月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4a7e39b-3f6e-5df1-99b3-77b0cde95d4c"}, {"title": "本纪记十一月初一发生日食", "description": "宣德十年十一月初一，发生日食。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年十一月戊辰朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "534cbac7-2050-5941-a145-17bec255817c"}, {"title": "阿台、朵儿只伯进犯凉州镇番，陈懋在黑山击败其部", "description": "宣德十年十二月壬子，阿台和朵儿只伯所部进犯凉州、镇番。明军总兵陈懋在黑山击败他们。", "start_year": 1436, "end_year": 1436, "time_original": "宣德十年十二月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02613d81-8925-5c46-8937-635811faa951"}, {"title": "本纪汇记宣德十年多地入贡", "description": "宣德十年，琉球中山、暹罗、日本、占城、安南、满剌加、哈密和瓦剌入贡。 按原历纪年，事情发生在公元1435至1436年之间。", "start_year": null, "end_year": null, "time_original": "宣德十年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33bee997-80e0-5d63-8be5-a4189e14440f"}, {"title": "明廷停止铜仁金场事务", "description": "正统元年正月丙戌，明廷停办铜仁金场。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年正月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b9463e63-7e71-544c-9b74-245dfd0fdc86"}, {"title": "明廷派三万禁军到京畿屯田", "description": "正统元年正月庚寅，朝廷派三万禁军在京畿一带屯田。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年正月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aa1144d7-c6bc-5f9a-bd0f-786315edb0c0"}, {"title": "明廷授周旋等人不同等第的进士资格", "description": "正统元年三月己巳，朝廷授予周旋等人不同等第的进士资格。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年三月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf99dcf4-137b-5e69-8b81-be715e65b5cd"}, {"title": "明英宗参加经筵", "description": "正统元年三月乙亥，明英宗朱祁镇参加由儒臣讲解经史的经筵。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年三月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d78214c-1518-5ccc-83fb-538ae8ad8e3d"}, {"title": "明英宗在太庙祭祀", "description": "正统元年四月初一，明英宗朱祁镇到太庙祭祀。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年四月丁酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02457b86-72e4-5f16-9471-46336302ceb2"}, {"title": "阿台、朵儿只伯所部进攻肃州", "description": "正统元年五月丁卯，阿台和朵儿只伯所部进攻肃州。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年五月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3a6db7d4-2029-5240-98c2-fafb934134d4"}, {"title": "明廷设置提督学校官", "description": "正统元年五月壬辰，朝廷设置负责各地学校事务的提督学校官。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年五月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62b2a028-3b0a-5f17-90c1-a4eacb999ff9"}, {"title": "蒋贵、赵安奉命出征阿台和朵儿只伯", "description": "正统元年八月甲戌，朝廷任右都督蒋贵为总兵官、都督同知赵安为副手，领军征讨阿台和朵儿只伯。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07998ab1-fa43-5274-81c5-d9bd917458c1"}, {"title": "何文渊等奉命到两淮、长芦和浙江督办盐课", "description": "正统元年九月癸卯，明廷派侍郎何文渊、王佐和副都御史朱与言督办两淮、长芦和浙江盐课。本纪记此为钦差巡盐的起点。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年九月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9b67059e-fae2-5399-9d26-391c1a8f5e81"}, {"title": "明廷册封黎麟为安南国王", "description": "正统元年九月庚申，明廷册封黎利的儿子黎麟为安南国王。《安南传》又记麟一名龙。", "start_year": 1436, "end_year": 1436, "time_original": "正统元年九月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2afd12fd-57ce-5502-b789-7b02a99cef65"}, {"title": "明廷命京官举荐御史、知县人选", "description": "正统元年十一月乙卯，朝廷要求三品以上京官分别举荐一位可任御史者，四品官及侍从、言官分别举荐一位可任知县者。", "start_year": 1437, "end_year": 1437, "time_original": "正统元年十一月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b45f4bf9-e4a6-5ab5-a5bb-ee68dfba0841"}, {"title": "明廷减免湖广受灾地区税粮", "description": "正统元年十一月，朝廷豁免湖广灾区应缴税粮。 按原历纪年，事情发生在公元1436至1437年之间。", "start_year": null, "end_year": null, "time_original": "正统元年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c4a721e-acd4-5c21-a34c-0da01a25615f"}, {"title": "王骥被投入监狱，不久获释", "description": "正统元年（年号对照1436年）十二月，王骥被投入监狱，不久获释。按原历月份对照，这项行动发生在公元1437年。", "start_year": 1437, "end_year": 1437, "time_original": "正统元年（年号对照1436年）十二月；公元年核为1437年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "a28b125b-3b9e-59df-9def-2f5b0b4fd4c6"}, {"title": "邝埜因边务议处迟延被下狱，随后获释", "description": "正统元年十二月丁丑，朝廷将兵部侍郎邝埜与尚书王骥一同下狱，两人后来获释。", "start_year": 1437, "end_year": 1437, "time_original": "正统元年十二月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15af3734-0009-549a-a403-2994fd94ba2b"}, {"title": "萧授率军平息广西蒙顾十六洞战事", "description": "正统元年十二月乙酉，湖广、贵州总兵官萧授出兵征讨广西蒙顾十六洞一带与明廷交战的部众，本纪记当地战事平息。", "start_year": 1437, "end_year": 1437, "time_original": "正统元年十二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0b4a7d25-1ae8-55c2-b0bb-08ae2fd9c6b9"}, {"title": "本纪汇记正统元年多地入贡", "description": "正统元年，琉球中山、爪哇、安南、乌斯藏、占城和瓦剌入贡。 按原历纪年，事情发生在公元1436至1437年之间。", "start_year": null, "end_year": null, "time_original": "正统元年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "857aa89c-0b9d-58f2-84d2-8d78ffa69d92"}, {"title": "明廷送古里、苏门答剌等十一国使者回国", "description": "正统元年，明廷送宣德年间来贡的古里、苏门答剌等十一国使者回国。 按原历纪年，事情发生在公元1436至1437年之间。", "start_year": null, "end_year": null, "time_original": "正统元年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "01aa70ba-a17e-5b3d-879a-3b27297d6c46"}, {"title": "明宣宗朱瞻基在乾清宫去世", "description": "宣德十年正月乙亥，明宣宗朱瞻基在乾清宫去世，本纪记享年三十八。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3ce7688-32a8-5b4d-971a-943718c2eaba"}, {"title": "明宣宗册立长子朱祁镇为皇太子", "description": "宣德三年二月戊午，明宣宗朱瞻基立皇长子朱祁镇为皇太子。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年二月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33ba34cf-e2fb-5ceb-99cb-251d68088a78"}, {"title": "明宣宗废胡皇后，册立孙贵妃为皇后", "description": "宣德三年三月癸未，明宣宗朱瞻基废去胡善祥的皇后名位，改立贵妃孙氏为皇后。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年三月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d171c24-10d0-5e80-b388-6d8a9f551861"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

