INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "朱祁镇即皇帝位。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001429；宣德十年正月壬午", "note": "原文：宣德十年春正月，宣宗崩，壬午，即皇帝位；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "e9189a9a-8ffa-591a-83fd-dd01e3319f58", "subject_id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf", "source_id": "ddb1e86e-5026-53c4-b623-639595687f97"}, {"subject_table": "person", "field_path": "description", "claim_text": "卷十本纪称朱祁镇的母亲为贵妃孙氏。卷一一三《后妃传》称孙氏将宫人之子作为自己的儿子，并称英宗生母最终无人知晓。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001427；身世记述", "note": "原文：母貴妃孫氏；核对说明：卷十与后妃传有不同记述，保留本纪原文与后妃传说法。生母待考。", "status": "draft", "id": "82251b70-63cd-5468-9c05-c9fdaaf3a188", "subject_id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf", "source_id": "8bbb71e4-f654-54d8-8636-0f7df0d2c3e9"}, {"subject_table": "event", "field_path": "description", "claim_text": "宣德十年正月壬午，明宣宗去世后，皇太子朱祁镇即位，是为明英宗。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001429；宣德十年正月壬午", "note": "原文：宣德十年春正月，宣宗崩，壬午，即皇帝位；核对说明：年表和本纪同记朱祁镇于宣德十年正月即位，本纪补壬午日。", "status": "draft", "id": "6b9f7676-0a9b-5dad-b198-8f226e22d4e3", "subject_id": "66d261b1-d254-582b-91e0-5cf32aedba56", "source_id": "ddb1e86e-5026-53c4-b623-639595687f97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历宣德十年正月壬午。DDBC历表换算所据为1435-02-16至1435-02-16，据此核对公元发生年份。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001429；宣德十年正月壬午", "note": "原文：宣德十年春正月，宣宗崩，壬午，即皇帝位；核对说明：年表和本纪同记朱祁镇于宣德十年正月即位，本纪补壬午日。", "status": "draft", "id": "9621c801-a1e5-54db-9bd8-16ca57f65cde", "subject_id": "66d261b1-d254-582b-91e0-5cf32aedba56", "source_id": "ddb1e86e-5026-53c4-b623-639595687f97"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "即皇帝位", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001429；宣德十年正月壬午", "note": "原文：宣